const inputItems = $input.all();

if (!inputItems.length) {
  throw new Error('Nenhum item recebido do Webhook.');
}

const webhookItem = inputItems[0];
const inputJson = webhookItem.json ?? {};
const body =
  inputJson.body && typeof inputJson.body === 'object'
    ? inputJson.body
    : inputJson;

const binaries = webhookItem.binary ?? {};
const fileKeys = Object.keys(binaries)
  .filter((key) => /^arquivos\d+$/i.test(key))
  .sort((a, b) => {
    const na = Number((a.match(/\d+/) || ['0'])[0]);
    const nb = Number((b.match(/\d+/) || ['0'])[0]);
    return na - nb;
  });

if (fileKeys.length === 0) {
  throw new Error('Nenhum arquivo XML encontrado. Esperado: arquivos0, arquivos1, arquivos2...');
}

const output = [];

for (const key of fileKeys) {
  const bin = binaries[key];
  if (!bin) continue;

  let buffer;
  try {
    buffer = await this.helpers.getBinaryDataBuffer(0, key);
  } catch (error) {
    throw new Error(`Falha ao ler o binário real do campo ${key}: ${error.message}`);
  }

  let xmlString = buffer.toString('utf8');

  xmlString = xmlString
    .replace(/^\uFEFF/, '')
    .replace(/^\s+/, '')
    .replace(/^[^<]+(?=<)/, '')
    .trim();

  if (!xmlString) {
    throw new Error(`O arquivo do campo ${key} foi lido, mas está vazio.`);
  }

  if (!xmlString.startsWith('<')) {
    throw new Error(`O conteúdo do campo ${key} não parece ser XML válido. Início encontrado: ${xmlString.substring(0, 80)}`);
  }

  output.push({
    json: {
      cliente_id: body.cliente_id ?? null,
      tipo_operacao: body.tipo_operacao ?? 'Entrada',
      upload_field: key,
      nome_arquivo: bin.fileName ?? `${key}.xml`,
      mime_type: bin.mimeType ?? 'application/xml',
      file_extension: bin.fileExtension ?? 'xml',
      xml_text: xmlString
    },
    binary: {
      data: bin
    },
    pairedItem: {
      item: 0
    }
  });
}

return output;

const items = $input.all();

function money(v) {
  const n = parseFloat(v);
  return Number.isFinite(n) ? n : 0;
}

const origemItems = $('Separar XMLs').all();

for (let i = 0; i < items.length; i++) {
  const data = items[i].json ?? {};

  let nfe = {};

  if (data.nfeProc?.NFe?.infNFe) {
    nfe = data.nfeProc.NFe.infNFe;
  } else if (data.NFe?.infNFe) {
    nfe = data.NFe.infNFe;
  } else if (data.infNFe) {
    nfe = data.infNFe;
  } else {
    throw new Error(`Estrutura NFe inválida no item ${i + 1}`);
  }

  const ide = nfe.ide ?? {};
  const emit = nfe.emit ?? {};
  const dest = nfe.dest ?? {};
  const tot = nfe.total?.ICMSTot ?? {};

  let chave = '';
  if (nfe.$?.Id) {
    chave = String(nfe.$.Id).replace(/^NFe/, '');
  } else if (nfe.Id) {
    chave = String(nfe.Id).replace(/^NFe/, '');
  }

  const origem = origemItems[i]?.json ?? {};

  items[i].json = {
    cliente_id: origem.cliente_id ?? null,
    tipo_operacao: origem.tipo_operacao ?? 'Entrada',
    nome_arquivo: origem.nome_arquivo ?? '',
    upload_field: origem.upload_field ?? '',

    chave_acesso: chave,
    numero_nota: ide.nNF ?? '',
    serie: ide.serie ?? '',
    data_emissao: ide.dhEmi
      ? String(ide.dhEmi).substring(0, 19).replace('T', ' ')
      : null,

    emitente_nome: emit.xNome ?? '',
    emitente_cnpj: emit.CNPJ ?? emit.CPF ?? '',

    destinatario_nome: dest.xNome ?? '',
    destinatario_cnpj: dest.CNPJ ?? dest.CPF ?? '',

    valor_total_nota: money(tot.vNF),
    base_icms: money(tot.vBC),
    valor_icms: money(tot.vICMS),
    valor_pis: money(tot.vPIS),
    valor_cofins: money(tot.vCOFINS)
  };
}

return items;

const pastaItems = $input.all();
const fiscais = $('Extrair Dados NFe').all();
const separados = $('Separar XMLs').all();

const out = [];

for (let i = 0; i < pastaItems.length; i++) {
  const pasta = pastaItems[i].json ?? {};
  const fiscal = fiscais[i]?.json ?? {};
  const binario = separados[i]?.binary ?? {};

  if (!pasta.id_pasta_raiz) {
    throw new Error(`id_pasta_raiz não encontrado no item ${i + 1}`);
  }

  if (!binario.data) {
    throw new Error(`Binário 'data' não encontrado no item ${i + 1}`);
  }

  out.push({
    json: {
      ...fiscal,
      id_pasta_raiz: pasta.id_pasta_raiz
    },
    binary: {
      data: binario.data
    }
  });
}

return out;

const driveItems = $input.all();
const fiscais = $('Consolidar Dados + Binário').all();

const out = [];

for (let i = 0; i < driveItems.length; i++) {
  const drive = driveItems[i].json ?? {};
  const fiscal = fiscais[i]?.json ?? {};

  if (!fiscal.cliente_id) {
    throw new Error(`cliente_id não encontrado no item ${i + 1}`);
  }

  out.push({
    json: {
      cliente_id: fiscal.cliente_id ?? null,
      tipo_operacao: fiscal.tipo_operacao ?? 'Entrada',
      nome_arquivo: fiscal.nome_arquivo ?? '',

      chave_acesso: fiscal.chave_acesso ?? '',
      numero_nota: fiscal.numero_nota ?? '',
      serie: fiscal.serie ?? '',
      data_emissao: fiscal.data_emissao ?? null,

      emitente_nome: fiscal.emitente_nome ?? '',
      emitente_cnpj: fiscal.emitente_cnpj ?? '',
      destinatario_nome: fiscal.destinatario_nome ?? '',
      destinatario_cnpj: fiscal.destinatario_cnpj ?? '',

      valor_total_nota: Number(fiscal.valor_total_nota ?? 0),
      base_icms: Number(fiscal.base_icms ?? 0),
      valor_icms: Number(fiscal.valor_icms ?? 0),
      valor_pis: Number(fiscal.valor_pis ?? 0),
      valor_cofins: Number(fiscal.valor_cofins ?? 0),

      arquivo_drive_id: drive.id ?? '',
      arquivo_url_drive: drive.webViewLink ?? drive.webContentLink ?? drive.id ?? ''
    }
  });
}

return out;

const items = $input.all();

function esc(v) {
  return String(v ?? '').replace(/'/g, "''");
}

return items.map((item) => {
  const j = item.json ?? {};

  return {
    json: {
      cliente_id: Number(j.cliente_id ?? 0),
      tipo_operacao: esc(j.tipo_operacao),
      nome_arquivo: esc(j.nome_arquivo),

      chave_acesso: esc(j.chave_acesso),
      numero_nota: esc(j.numero_nota),
      serie: esc(j.serie),
      data_emissao: j.data_emissao ? esc(j.data_emissao) : null,

      emitente_nome: esc(j.emitente_nome),
      emitente_cnpj: esc(j.emitente_cnpj),
      destinatario_nome: esc(j.destinatario_nome),
      destinatario_cnpj: esc(j.destinatario_cnpj),

      valor_total_nota: Number(j.valor_total_nota ?? 0),
      base_icms: Number(j.base_icms ?? 0),
      valor_icms: Number(j.valor_icms ?? 0),
      valor_pis: Number(j.valor_pis ?? 0),
      valor_cofins: Number(j.valor_cofins ?? 0),

      arquivo_drive_id: esc(j.arquivo_drive_id),
      arquivo_url_drive: esc(j.arquivo_url_drive)
    }
  };
});

const total = $input.all().length;
return [{
  json: {
    success: true,
    message: 'XML(s) processado(s), arquivado(s) e salvo(s) com sucesso.',
    arquivos_processados: total
  }
}];
